import RNA
import random

target = "......((.......((.((.......((.((...............)).........((...............)).)).......)).((.......((...............)).......)).((.......((.((...............)).........((...............)).)).......)).((.......((...............)).......)).((.......((.((...............)).........((...............)).)).......)).((.......((...........((...............)).)).......)).)).......))......"
n=len(target)

stack=[]
pairs=[-1]*n
for i,c in enumerate(target):
    if c=='(':
        stack.append(i)
    elif c==')':
        j=stack.pop()
        pairs[i]=j
        pairs[j]=i

def score(ss):
    return sum(1 for x,y in zip(ss,target) if x!=y)

def build_seq():
    seq=['A']*n
    for i in range(n):
        if pairs[i]>i:
            seq[i]='G'
            seq[pairs[i]]='C'
    return ''.join(seq)

base=build_seq()
random.seed(42)
cur=list(base)
fc=RNA.fold_compound(''.join(cur)); ss,mfe=fc.mfe()
cur_score=score(ss)
cur_mfe=mfe
print("start", cur_score, "mfe", mfe)

best=(cur_score, ''.join(cur))

for step in range(200000):
    i=random.randrange(n)
    old=cur[i]
    j=None
    if pairs[i]>=0:
        pc=random.choice(['GC','CG','AU','UA','GU','UG'])
        cur[i]=pc[0]; cur[pairs[i]]=pc[1]
        j=pairs[i]
        oldp=cur[i]
    else:
        cur[i]=random.choice('ACGU')
    fc=RNA.fold_compound(''.join(cur)); ss,mfe=fc.mfe()
    s=score(ss)
    if s < cur_score or (s==cur_score and mfe <= cur_mfe + 0.01):
        cur_score=s; cur_mfe=mfe
        if s < best[0]:
            best=(s,''.join(cur))
            print("step",step,"score",s)
        if s==0:
            print("SOLVED",''.join(cur)); break
    else:
        cur[i]=old
        if j is not None:
            cur[j]=oldp if 'oldp' in dir() else cur[j]
print("best score", best[0])
print(best[1])

